package app.layan.quran;
import android.app.*;import android.os.*;import android.content.*;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.text.Normalizer;import java.util.*;import java.util.concurrent.*;

public final class HadithActivity extends LayanBaseActivity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler handler=new Handler(Looper.getMainLooper());private List<Book> books=new ArrayList<>();private List<Item> loaded=new ArrayList<>(),visible=new ArrayList<>();private ListView list;private TextView count;private Spinner chapters;private EditText search;private Book current;private int generation;private Runnable searchTask;private String section="",query="";private boolean updatingChapters;
 private static final class Book {String id,name,file;int count;Book(JSONObject o){id=o.optString("identifier");name=o.optString("name");file=o.optString("file");count=o.optInt("count");}}
 private static final class Item {int number;String text,book,grade;Item(int n,String t,String b,String g){number=n;text=t;book=b;grade=g;}}
 @Override protected void onCreate(Bundle state){super.onCreate(state);if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::back);frame("الأحاديث","مكتبة الأحاديث · تعمل دون إنترنت");body.addView(new ProgressBar(this));String restoreId=state==null?"":state.getString("collection","");query=state==null?"":state.getString("query","");section=state==null?"":state.getString("chapter","");worker.execute(()->{try{JSONArray items=new JSONObject(read("content/hadith/index.json")).getJSONArray("items");List<Book> out=new ArrayList<>();for(int i=0;i<items.length();i++)out.add(new Book(items.getJSONObject(i)));runOnUiThread(()->{if(isDestroyed())return;books=out;Book restore=null;for(Book b:books)if(b.id.equals(restoreId))restore=b;if(restore==null)home();else open(restore);});}catch(Exception e){runOnUiThread(()->error("تعذّر فتح فهرس الأحاديث"));}});}
 private String read(String path)throws IOException{try(InputStream in=getAssets().open(path);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] data=new byte[8192];int n;while((n=in.read(data))!=-1)out.write(data,0,n);return out.toString("UTF-8");}}
 private void home(){generation++;handler.removeCallbacksAndMessages(null);current=null;query="";section="";loaded=new ArrayList<>();visible=new ArrayList<>();frame("الأحاديث","اختر كتابًا للقراءة والبحث");ListView rows=new ListView(this);rows.setDividerHeight(1);rows.setAdapter(new BaseAdapter(){public int getCount(){return books.size();}public Object getItem(int n){return books.get(n);}public long getItemId(int n){return n;}public View getView(int n,View v,ViewGroup p){Book b=books.get(n);LinearLayout r=row();r.setPadding(dp(20),dp(12),dp(20),dp(12));LinearLayout titles=column();titles.addView(label(b.name,24,ink));titles.addView(label(digits(b.count+" حديثًا"),13,muted));r.addView(titles,new LinearLayout.LayoutParams(0,-2,1));r.addView(label("‹",24,green));return r;}});rows.setOnItemClickListener((p,v,n,id)->open(books.get(n)));body.addView(rows,new LinearLayout.LayoutParams(-1,-1));}
 private void open(Book book){current=book;int token=++generation;frame(book.name,"بحث في النص أو رقم الحديث");LinearLayout controls=column();controls.setPadding(dp(18),0,dp(18),dp(8));search=new EditText(this);search.setSingleLine(true);search.setHint("ابحث في الأحاديث");search.setTextColor(ink);search.setHintTextColor(muted);search.setTextSize(16);search.setPadding(dp(14),0,dp(14),0);search.setBackground(cardBackground(paper));search.setText(query);controls.addView(search,new LinearLayout.LayoutParams(-1,dp(50)));chapters=new Spinner(this);controls.addView(chapters,new LinearLayout.LayoutParams(-1,dp(48)));count=label("جارٍ تحميل الكتاب…",13,muted);controls.addView(count);body.addView(controls);list=new ListView(this);list.setDividerHeight(1);body.addView(list,new LinearLayout.LayoutParams(-1,0,1));worker.execute(()->{try{JSONObject root=new JSONObject(read("content/"+book.file));JSONObject metadata=root.optJSONObject("metadata"),sections=metadata==null?null:metadata.optJSONObject("sections");JSONArray items=root.getJSONArray("hadiths");List<Item> out=new ArrayList<>();LinkedHashSet<String> names=new LinkedHashSet<>();for(int i=0;i<items.length();i++){JSONObject o=items.getJSONObject(i);String text=o.optString("text");if(text.trim().isEmpty())continue;JSONObject ref=o.optJSONObject("reference");String name=ref!=null&&sections!=null?sections.optString(String.valueOf(ref.optInt("book",-1))):"";if(!name.isEmpty())names.add(name);StringBuilder grades=new StringBuilder();JSONArray gs=o.optJSONArray("grades");if(gs!=null)for(int j=0;j<gs.length();j++){JSONObject g=gs.getJSONObject(j);if(grades.length()>0)grades.append('\n');grades.append(g.optString("name")).append(": ").append(g.optString("grade"));}out.add(new Item(o.optInt("hadithnumber",i+1),text,name,grades.toString()));}runOnUiThread(()->{if(isDestroyed()||token!=generation)return;loaded=out;List<String> options=new ArrayList<>();options.add("كل الأبواب");options.addAll(names);updatingChapters=true;ArrayAdapter<String> adapter=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_item,options);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);chapters.setAdapter(adapter);chapters.setSelection(Math.max(0,options.indexOf(section)));updatingChapters=false;chapters.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int n,long id){if(updatingChapters)return;section=n==0?"":options.get(n);filter();}public void onNothingSelected(AdapterView<?> p){}});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int c,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){query=s.toString();if(searchTask!=null)handler.removeCallbacks(searchTask);searchTask=()->filter();handler.postDelayed(searchTask,220);}public void afterTextChanged(Editable e){}});filter();});}catch(Exception e){runOnUiThread(()->{if(token==generation)error("تعذّر قراءة هذا الكتاب، أعد فتحه");});}});}
 private static String normalize(String t){t=Normalizer.normalize(t,Normalizer.Form.NFD).replaceAll("\\p{M}+","").replace("ـ","").replace('أ','ا').replace('إ','ا').replace('آ','ا').replace('ى','ي');StringBuilder b=new StringBuilder();for(char c:t.toLowerCase(Locale.ROOT).toCharArray())b.append(c>='٠'&&c<='٩'?(char)('0'+c-'٠'):c);return b.toString().trim();}
 private void filter(){int token=++generation;String q=normalize(query),chapter=section;List<Item> source=loaded;worker.execute(()->{List<Item> results=new ArrayList<>();for(Item h:source)if((chapter.isEmpty()||chapter.equals(h.book))&&(q.isEmpty()||String.valueOf(h.number).equals(q)||normalize(h.text+" "+h.book).contains(q)))results.add(h);runOnUiThread(()->{if(isDestroyed()||token!=generation||current==null)return;visible=results;count.setText(digits(results.size()+" حديثًا"));list.setAdapter(new BaseAdapter(){public int getCount(){return visible.size();}public Object getItem(int n){return visible.get(n);}public long getItemId(int n){return visible.get(n).number;}public View getView(int n,View old,ViewGroup p){Item h=visible.get(n);LinearLayout item=column();item.setPadding(dp(20),dp(16),dp(20),dp(16));item.addView(label(current.name+" · "+digits(""+h.number),14,green));if(!h.book.isEmpty())item.addView(label(h.book,15,muted));TextView text=label(h.text,prefs.getInt("hadith_font",21),ink);text.setMaxLines(7);text.setEllipsize(android.text.TextUtils.TruncateAt.END);text.setLineSpacing(dp(5),1f);item.addView(text);return item;}});list.setOnItemClickListener((p,v,n,id)->detail(visible.get(n)));});});}
 private void detail(Item h){LinearLayout content=card();TextView title=label(current.name+" · حديث "+digits(""+h.number),20,green);content.addView(title);if(!h.book.isEmpty())content.addView(label(h.book,18,muted));TextView text=label(h.text,prefs.getInt("hadith_font",21),ink);text.setTextIsSelectable(true);text.setLineSpacing(dp(7),1f);content.addView(text);if(!h.grade.isEmpty()){gap(content,12);content.addView(label(h.grade,15,muted));}ScrollView scroll=new ScrollView(this);scroll.addView(content);String shareText=h.text+"\n"+current.name+" · "+h.number;new LayanDialogBuilder(this).setView(scroll).setPositiveButton("تم",null).setNeutralButton("مشاركة",(d,w)->{Intent i=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,shareText);startActivity(Intent.createChooser(i,"مشاركة الحديث"));}).setNegativeButton("حجم الخط",(d,w)->{String[] sizes={"صغير","متوسط","كبير"};new LayanDialogBuilder(this).setItems(sizes,(dialog,n)->{prefs.edit().putInt("hadith_font",new int[]{18,21,25}[n]).apply();detail(h);}).show();}).show();}
 private void error(String message){if(isDestroyed())return;body.removeAllViews();body.addView(label(message,18,ink));body.addView(button("عودة إلى الكتب",this::home));}
 private void back(){if(current!=null)home();else finish();}
 @Override public void onBackPressed(){if(Build.VERSION.SDK_INT<33)back();else super.onBackPressed();}
 @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(current!=null)state.putString("collection",current.id);state.putString("query",query);state.putString("chapter",section);}
 @Override protected void onDestroy(){generation++;handler.removeCallbacksAndMessages(null);worker.shutdownNow();super.onDestroy();}
}
